/**
 * The Yoke
 * ----------
 * The Lord tells Jeremiah to make a yoke of leather and wood and wear it; Hananiah breaks the yoke and the prophet says the Lord will make yokes of iron. Stage: a market square at noon, a wooden yoke on a prophet's shoulders, a false prophet snapping it, an iron yoke in the shadow; a hot day, a cold word.
 *
 * Palette 0x1a2a14 → 0x060402 · light: ember · hero: pillar
 *
 * Generated by scripts/add-shot-scenes.mjs from the act data and
 * the mood board in ../../art/. Composition follows the kit in
 * ./jeremiah-kit.js.
 */

import { THREE, createScene, oak, pillar, person } from './jeremiah-kit.js';

const BG = 0x1a2a14;
const GROUND = 0x060402;

export function build(group) {
    const W = createScene(group, { seed: 3335932768, bg: BG, fogNear: 45, fogFar: 180 });

    /* light — ember */
    W.lights({ sky: 0x3a2418, gnd: 0x1a0e08, hemi: 0.4, sun: 0xff7a30, sunI: 0.7, sunPos: [20, 26, 30] });

    W.stars(90, 150, [0xf0e0c8, 0xd8c0a0], 0.7);
    W.disc([0, 34, -150], 14, 0xff8a30, 0.12);

    /* ground */
    W.ground(260, 260, 0, 0, 0x060402, { amp: 0.6, j: 0.3, flat: 30, rise: (x, z) => Math.sin(x * 0.05) * Math.cos(z * 0.04) * 1.2 });

    /* trees: broadleaf shade */
    oak(W, group, -33.8, 0, 3.2, 1.20, { leaf: 0x4f8a2e, leaf2: 0x5fa036 });
    oak(W, group, 47.3, 0, -3.8, 1.23, { leaf: 0x4f8a2e, leaf2: 0x5fa036 });
    oak(W, group, 23.5, 0, -5.7, 1.25, { leaf: 0x4f8a2e, leaf2: 0x5fa036 });

    /* hero: the standing stone */
    pillar(W, group, 0, 0, 0, 1.15, { stone: 0x060402 });
    W.disc([0, 6, -12], 5, 0x22371a, 0.3);

    /* figures */
    person(W, group, [-5, 0, 5], { robe: 0x8a6a44, head: 'wrap', wrap: 0x1e3017, wrapTrim: 0x121d0e, beard: 'long', staff: 'planted', ry: 0.19, s: 1.01 });
    person(W, group, [4.5, 0, 6], { robe: 0x8a6a44, head: 'wrap', wrap: 0x1e3017, wrapTrim: 0x121d0e, beard: 'long', staff: 'planted', ry: -0.60, s: 1.13 });
    person(W, group, [1, 0, -5], { robe: 0x8a6a44, head: 'wrap', wrap: 0x1e3017, wrapTrim: 0x121d0e, beard: 'long', staff: 'planted', ry: 0.47, s: 1.10 });

    return W.finish();
}

export default { build };
